class Solution {
  public boolean confusingNumber(int n) {
    int[] rot = {0, 1, -1, -1, -1, -1, 9, -1, 8, 6};
    long rotated = 0;
    for (int x = n; x > 0; x /= 10) {
      int d = rot[x % 10];
      if (d < 0) return false;
      rotated = rotated * 10 + d;
    }
    return rotated != n;
  }
}
